package com.example.shop.ops;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Component
public class ReportJob {

    private static final Logger log = LoggerFactory.getLogger(ReportJob.class);

    public void run(String name, int rows) {
        log.info("Report {} produced {} rows", name, rows);
        try {
            export(name);
        } catch (IllegalStateException e) {
            log.error("Export of report {} failed", name, e);   // exception last: full stack trace
        }
    }

    private void export(String name) {
        if (name.isBlank()) {
            throw new IllegalStateException("empty name");
        }
    }
}
